SET NAMES utf8mb4;
SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
START TRANSACTION WITH CONSISTENT SNAPSHOT, READ ONLY;
SELECT JSON_OBJECT('grupo', 'meta', 'datos', JSON_OBJECT(
            'base', DATABASE(), 'servidor', @@server_uuid, 'version', VERSION(),
            'fecha', UTC_TIMESTAMP(), 'readonly', 1));
SELECT JSON_OBJECT('grupo', 'columnas', 'datos', JSON_OBJECT('TABLE_NAME', `TABLE_NAME`, 'COLUMN_NAME', `COLUMN_NAME`, 'COLUMN_TYPE', `COLUMN_TYPE`, 'IS_NULLABLE', `IS_NULLABLE`, 'COLUMN_DEFAULT', `COLUMN_DEFAULT`, 'EXTRA', `EXTRA`, 'COLLATION_NAME', `COLLATION_NAME`)) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME IN ('almacenista_supervisores', 'asignacion_estado_historiales', 'asignacion_movimientos', 'asignacion_periodos', 'asignaciones_inventarios', 'bodega_usuario_operativa', 'bodegas', 'colaboradores', 'compra_consolidado', 'compra_detalle_consolidado', 'compra_detalles', 'compras', 'entregas_inventario', 'inventario_existencias', 'inventario_lotes_operativos', 'inventarios', 'migrations', 'movimientos', 'procesos_inspeccion', 'productos', 'proveedores', 'region_coordinador_historial', 'region_coordinador_operativo', 'region_usuario_operativa', 'regiones', 'roles', 'sistema_ajustes', 'sistema_campo_valores', 'sistema_campos', 'sistema_permisos_usuario', 'users');
