SELECT JSON_OBJECT('grupo', 'relaciones', 'datos', JSON_OBJECT('TABLE_NAME', `TABLE_NAME`, 'CONSTRAINT_NAME', `CONSTRAINT_NAME`, 'COLUMN_NAME', `COLUMN_NAME`, 'REFERENCED_TABLE_NAME', `REFERENCED_TABLE_NAME`, 'REFERENCED_COLUMN_NAME', `REFERENCED_COLUMN_NAME`)) FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME IN ('almacenista_supervisores', 'asignacion_estado_historiales', 'asignacion_movimientos', 'asignacion_periodos', 'asignaciones_inventarios', 'bodega_usuario_operativa', 'bodegas', 'colaboradores', 'compra_consolidado', 'compra_detalle_consolidado', 'compra_detalles', 'compras', 'entregas_inventario', 'inventario_existencias', 'inventario_lotes_operativos', 'inventarios', 'migrations', 'movimientos', 'procesos_inspeccion', 'productos', 'proveedores', 'region_coordinador_historial', 'region_coordinador_operativo', 'region_usuario_operativa', 'regiones', 'roles', 'sistema_ajustes', 'sistema_campo_valores', 'sistema_campos', 'sistema_permisos_usuario', 'users') AND REFERENCED_TABLE_NAME IS NOT NULL;
SELECT JSON_OBJECT('grupo', 'reglas_foraneas', 'datos', JSON_OBJECT('TABLE_NAME', `TABLE_NAME`, 'REFERENCED_TABLE_NAME', `REFERENCED_TABLE_NAME`, 'CONSTRAINT_NAME', `CONSTRAINT_NAME`, 'UPDATE_RULE', `UPDATE_RULE`, 'DELETE_RULE', `DELETE_RULE`)) FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA = DATABASE() AND TABLE_NAME IN ('almacenista_supervisores', 'asignacion_estado_historiales', 'asignacion_movimientos', 'asignacion_periodos', 'asignaciones_inventarios', 'bodega_usuario_operativa', 'bodegas', 'colaboradores', 'compra_consolidado', 'compra_detalle_consolidado', 'compra_detalles', 'compras', 'entregas_inventario', 'inventario_existencias', 'inventario_lotes_operativos', 'inventarios', 'migrations', 'movimientos', 'procesos_inspeccion', 'productos', 'proveedores', 'region_coordinador_historial', 'region_coordinador_operativo', 'region_usuario_operativa', 'regiones', 'roles', 'sistema_ajustes', 'sistema_campo_valores', 'sistema_campos', 'sistema_permisos_usuario', 'users');
SELECT JSON_OBJECT('grupo', 'tablas', 'datos', JSON_OBJECT('TABLE_NAME', `TABLE_NAME`, 'ENGINE', `ENGINE`)) FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME IN ('almacenista_supervisores', 'asignacion_estado_historiales', 'asignacion_movimientos', 'asignacion_periodos', 'asignaciones_inventarios', 'bodega_usuario_operativa', 'bodegas', 'colaboradores', 'compra_consolidado', 'compra_detalle_consolidado', 'compra_detalles', 'compras', 'entregas_inventario', 'inventario_existencias', 'inventario_lotes_operativos', 'inventarios', 'migrations', 'movimientos', 'procesos_inspeccion', 'productos', 'proveedores', 'region_coordinador_historial', 'region_coordinador_operativo', 'region_usuario_operativa', 'regiones', 'roles', 'sistema_ajustes', 'sistema_campo_valores', 'sistema_campos', 'sistema_permisos_usuario', 'users');
SELECT JSON_OBJECT('grupo', 'disparadores', 'datos', JSON_OBJECT('EVENT_OBJECT_TABLE', `EVENT_OBJECT_TABLE`, 'ACTION_TIMING', `ACTION_TIMING`, 'EVENT_MANIPULATION', `EVENT_MANIPULATION`, 'TRIGGER_NAME', `TRIGGER_NAME`)) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA = DATABASE() AND EVENT_OBJECT_TABLE IN ('almacenista_supervisores', 'asignacion_estado_historiales', 'asignacion_movimientos', 'asignacion_periodos', 'asignaciones_inventarios', 'bodega_usuario_operativa', 'bodegas', 'colaboradores', 'compra_consolidado', 'compra_detalle_consolidado', 'compra_detalles', 'compras', 'entregas_inventario', 'inventario_existencias', 'inventario_lotes_operativos', 'inventarios', 'migrations', 'movimientos', 'procesos_inspeccion', 'productos', 'proveedores', 'region_coordinador_historial', 'region_coordinador_operativo', 'region_usuario_operativa', 'regiones', 'roles', 'sistema_ajustes', 'sistema_campo_valores', 'sistema_campos', 'sistema_permisos_usuario', 'users');
SELECT JSON_OBJECT('grupo', 'migraciones', 'datos', JSON_OBJECT('migration', `migration`)) FROM migrations;
SELECT JSON_OBJECT('grupo', 'general', 'datos', JSON_OBJECT('valor', `valor`)) FROM sistema_ajustes WHERE clave = 'general';
SELECT JSON_OBJECT('grupo', 'regiones', 'datos', JSON_OBJECT('id', `id`, 'nombre', `nombre`, 'activa', `activa`, 'coordinador_id', `coordinador_id`)) FROM regiones;
SELECT JSON_OBJECT('grupo', 'bodegas', 'datos', JSON_OBJECT('id', `id`, 'nombre', `nombre`, 'tipo', `tipo`, 'ubicacion', `ubicacion`)) FROM bodegas;
SELECT JSON_OBJECT('grupo', 'colaboradores', 'datos', JSON_OBJECT('codigo', `codigo`, 'nombre', `nombre`, 'puesto', `puesto`, 'estado', `estado`, 'region_id', `region_id`)) FROM colaboradores;
SELECT JSON_OBJECT('grupo', 'productos', 'datos', JSON_OBJECT('codigo', `codigo`, 'nombre', `nombre`, 'descripcion', `descripcion`, 'categoria', `categoria`, 'unidad_medida', `unidad_medida`, 'vida_util_meses', `vida_util_meses`)) FROM productos;
SELECT JSON_OBJECT('grupo', 'roles', 'datos', JSON_OBJECT('id', `id`, 'nombre', `nombre`, 'ambito_operativo', `ambito_operativo`, 'activo', `activo`)) FROM roles;
SELECT JSON_OBJECT('grupo', 'usuarios', 'datos', JSON_OBJECT('id', `id`, 'name', `name`, 'email', `email`, 'role_id', `role_id`, 'acceso_activo', `acceso_activo`, 'bodega_id', `bodega_id`, 'coordinador_id', `coordinador_id`)) FROM users;
SELECT JSON_OBJECT('grupo', 'supervisores', 'datos', JSON_OBJECT('supervisor_id', `supervisor_id`, 'almacenista_id', `almacenista_id`)) FROM almacenista_supervisores;
SELECT JSON_OBJECT('grupo', 'region_usuario', 'datos', JSON_OBJECT('user_id', `user_id`, 'region_id', `region_id`)) FROM region_usuario_operativa;
SELECT JSON_OBJECT('grupo', 'coordinadores', 'datos', JSON_OBJECT('user_id', `user_id`, 'region_id', `region_id`)) FROM region_coordinador_operativo;
SELECT JSON_OBJECT('grupo', 'bodega_usuario', 'datos', JSON_OBJECT('user_id', `user_id`, 'bodega_id', `bodega_id`, 'opera_inventario', `opera_inventario`, 'opera_requerimientos', `opera_requerimientos`)) FROM bodega_usuario_operativa;
SELECT JSON_OBJECT('grupo', 'reglas', 'datos', JSON_OBJECT('user_id', `user_id`, 'permiso', `permiso`, 'permitido', `permitido`)) FROM sistema_permisos_usuario;
SELECT JSON_OBJECT('grupo', 'saldos', 'datos', JSON_OBJECT('bodega_id', `bodega_id`, 'producto_codigo', `producto_codigo`, 'stock_tipo', `stock_tipo`, 'cantidad', `cantidad`)) FROM inventarios;
SELECT JSON_OBJECT('grupo', 'custodias', 'datos', JSON_OBJECT('id', `id`, 'colaborador_codigo', `colaborador_codigo`, 'producto_codigo', `producto_codigo`, 'bodega_id', `bodega_id`, 'cantidad_asignada', `cantidad_asignada`, 'fecha', `fecha`, 'stock_tipo', `stock_tipo`)) FROM asignaciones_inventarios WHERE estado = 'Activa';
SELECT JSON_OBJECT('grupo', 'proveedores', 'datos', JSON_OBJECT('id', `id`, 'nombre', `nombre`)) FROM proveedores;
SELECT JSON_OBJECT('grupo', 'facturas', 'datos', JSON_OBJECT('id', `id`, 'proveedor_id', `proveedor_id`, 'no_factura', `no_factura`, 'fecha_compra', `fecha_compra`, 'forma_pago', `forma_pago`)) FROM compras;
SELECT JSON_OBJECT('grupo', 'factura_lineas', 'datos', JSON_OBJECT('compra_id', `compra_id`, 'producto_codigo', `producto_codigo`, 'cantidad', `cantidad`, 'precio_unitario', `precio_unitario`)) FROM compra_detalles;
SELECT JSON_OBJECT('grupo', 'campos', 'datos', JSON_OBJECT('id', `id`, 'modulo', `modulo`, 'clave', `clave`, 'etiqueta', `etiqueta`, 'obligatorio', `obligatorio`, 'formulario', `formulario`, 'activo', `activo`, 'archivado_en', `archivado_en`)) FROM sistema_campos;
SELECT JSON_OBJECT('grupo', 'claves_personalizadas', 'datos', JSON_OBJECT('campo_id', `campo_id`, 'registro', `registro`)) FROM sistema_campo_valores;
SELECT JSON_OBJECT('grupo', 'procesos', 'datos', JSON_OBJECT('nombre', `nombre`, 'activo', `activo`)) FROM procesos_inspeccion;
COMMIT;
SELECT JSON_OBJECT('grupo', 'fin', 'datos', JSON_OBJECT('completo', 1));
